let watchlistReorderActive=false;
function unreadFor(pid){return events.filter(e=>e.p===pid&&e.type==='news'&&e.publishedAt>=Date.now()-7*86400000&&!state.read.includes(e.id)).length}
function orderedProjects(){return state.projects.map(id=>catalog.find(p=>p.id===id)).filter(Boolean).sort((a,b)=>Number(state.pinnedProjects.includes(b.id))-Number(state.pinnedProjects.includes(a.id)))}
renderProjectList=function(){
 if(watchlistReorderActive)return;
 const followed=orderedProjects(),list=followed.filter(p=>(p.name+' '+p.symbol+' '+(p.account||'')).toLowerCase().includes(projectListQuery.trim().toLowerCase())&&(!state.unreadProjectsOnly||unreadFor(p.id)>0));
 const sections=new Map();for(const p of list){const group=state.pinnedProjects.includes(p.id)?'置顶':state.projectGroups[p.id]||'未分组';if(!sections.has(group))sections.set(group,[]);sections.get(group).push(p)}
 $('#projects').innerHTML=[...sections].map(([group,items])=>`<section class="watchlist-group"><h4>${escapeHtml(group)} <span>${items.length}</span></h4>${items.map(p=>{const unread=unreadFor(p.id);return `<div class="watchlist-row" draggable="true" data-drag-project="${p.id}"><button class="watchlist-drag" data-reorder-handle="${p.id}" aria-label="排序 ${escapeHtml(p.name)}" title="拖动排序；方向键移动">⠿</button><button class="project-button ${state.project===p.id?'selected':''}" data-project="${p.id}" aria-current="${state.project===p.id?'page':'false'}" title="${escapeHtml(p.name)} · 近 7 天 ${unread} 条未读资讯">${token(p)}<span class="project-label"><strong>${escapeHtml(p.name)}</strong><span>${escapeHtml(p.symbol)}</span></span>${unread?`<small class="unread-badge">${unread>99?'99+':unread}</small>`:''}</button><button class="watchlist-more" data-watchlist-manage="${p.id}" aria-label="管理 ${escapeHtml(p.name)}">⋯</button></div>`}).join('')}</section>`).join('')||'<p class="project-list-empty">'+(state.unreadProjectsOnly?'暂无未读资讯项目':'暂无匹配项目，可从“管理”恢复关注')+'</p>';
 $('#project-count').textContent=followed.length;$('#unread-projects-only').checked=state.unreadProjectsOnly;
};
function saveWatchlist(){state.projectOrder=[...state.projects,...state.projectOrder.filter(id=>!state.projects.includes(id))];persist();render()}
function manageWatchlist(){
 showForm(`${formTitle('管理关注列表')}<p>分组、排序和关注状态保存到后台，同一私有站点的设备可同步。取消关注从你的阅读列表隐藏，不删除历史数据或暂停后台提醒。可拖动左侧项目排序，也可使用上下移按钮。</p><div class="watchlist-manager">${[...orderedProjects(),...catalog.filter(p=>state.hiddenProjects.includes(p.id))].map(p=>{const hidden=state.hiddenProjects.includes(p.id);return `<article class="watchlist-management-item">${token(p)}<div class="watchlist-management-content"><strong>${escapeHtml(p.name)} <small>${escapeHtml(p.symbol)}</small></strong><div class="watchlist-item-actions"><button data-follow-toggle="${p.id}">${hidden?'恢复关注':'取消关注'}</button>${!hidden?`<button data-pin-toggle="${p.id}">${state.pinnedProjects.includes(p.id)?'取消置顶':'置顶'}</button><button data-move-project="${p.id}" data-direction="-1" aria-label="上移 ${escapeHtml(p.name)}">↑</button><button data-move-project="${p.id}" data-direction="1" aria-label="下移 ${escapeHtml(p.name)}">↓</button>`:''}</div><label>分组<input aria-label="${escapeHtml(p.name)} 分组" data-project-group="${p.id}" maxlength="20" value="${escapeHtml(state.projectGroups[p.id]||'')}" placeholder="例如 AI / 基础设施"><button class="text-button" data-save-group="${p.id}">保存</button></label></div></article>`}).join('')}</div><div class="modal-footer"><button class="primary" data-close>完成</button></div>`);
}
$('#unread-projects-only').addEventListener('change',e=>{state.unreadProjectsOnly=e.target.checked;persist();renderProjectList()});
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;const d=b.dataset;
 if(d.watchlistManage!==undefined){manageWatchlist();return}
 if(d.followToggle){const id=d.followToggle;if(state.hiddenProjects.includes(id)){state.hiddenProjects=state.hiddenProjects.filter(x=>x!==id);if(!state.projects.includes(id))state.projects.push(id)}else{state.hiddenProjects.push(id);state.projects=state.projects.filter(x=>x!==id);if(state.project===id){state.project=null;state.view='feed'}}saveWatchlist();manageWatchlist()}
 if(d.saveGroup){state.projectGroups[d.saveGroup]=$('#form-dialog input[data-project-group="'+d.saveGroup+'"]').value.trim().slice(0,20);saveWatchlist();manageWatchlist();toast('分组已保存')}
 if(d.pinToggle){const id=d.pinToggle;state.pinnedProjects=state.pinnedProjects.includes(id)?state.pinnedProjects.filter(x=>x!==id):[...state.pinnedProjects,id];saveWatchlist();manageWatchlist()}
 if(d.moveProject){const i=state.projects.indexOf(d.moveProject),j=i+Number(d.direction);if(j>=0&&j<state.projects.length){[state.projects[i],state.projects[j]]=[state.projects[j],state.projects[i]];saveWatchlist();manageWatchlist()}}
});
document.addEventListener('change',e=>{const id=e.target.dataset.projectGroup;if(id){state.projectGroups[id]=e.target.value.trim().slice(0,20);saveWatchlist()}});
let draggingProject=null,touchDrag=null;
function dropAfter(row,x,y){const box=row.getBoundingClientRect();return window.innerWidth<=640?x>box.left+box.width/2:y>box.top+box.height/2}
function moveProject(source,target,after){const next=reorderProjects(state,source,target,after);if(next){Object.assign(state,next);saveWatchlist()}}
function clearDrop(){document.querySelectorAll('.drop-before,.drop-after').forEach(row=>row.classList.remove('drop-before','drop-after'))}
function showDrop(row,after){clearDrop();row.classList.add(after?'drop-after':'drop-before')}
function endReorder(){watchlistReorderActive=false;draggingProject=null;touchDrag=null;clearDrop();renderProjectList()}
document.addEventListener('dragstart',e=>{const row=e.target.closest('[data-drag-project]');if(row){draggingProject=row.dataset.dragProject;watchlistReorderActive=true;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',draggingProject)}});
document.addEventListener('dragover',e=>{const row=e.target.closest('[data-drag-project]');if(draggingProject&&row){e.preventDefault();showDrop(row,dropAfter(row,e.clientX,e.clientY))}});
document.addEventListener('drop',e=>{const row=e.target.closest('[data-drag-project]');if(!row||!draggingProject)return;e.preventDefault();const source=draggingProject;watchlistReorderActive=false;moveProject(source,row.dataset.dragProject,dropAfter(row,e.clientX,e.clientY));endReorder()});
document.addEventListener('dragend',endReorder);
document.addEventListener('pointerdown',e=>{const handle=e.target.closest('[data-reorder-handle]');if(!handle||e.pointerType==='mouse')return;e.preventDefault();handle.setPointerCapture(e.pointerId);touchDrag={source:handle.dataset.reorderHandle,pointer:e.pointerId};watchlistReorderActive=true});
document.addEventListener('pointermove',e=>{if(!touchDrag||touchDrag.pointer!==e.pointerId)return;const row=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-drag-project]');if(row){touchDrag.target=row.dataset.dragProject;touchDrag.after=dropAfter(row,e.clientX,e.clientY);showDrop(row,touchDrag.after)}else{touchDrag.target=null;clearDrop()}const list=$('#projects'),r=list.getBoundingClientRect();if(window.innerWidth<=640){if(e.clientX<r.left+25)list.scrollLeft-=15;else if(e.clientX>r.right-25)list.scrollLeft+=15}else{if(e.clientY<r.top+25)list.scrollTop-=15;else if(e.clientY>r.bottom-25)list.scrollTop+=15}});
document.addEventListener('pointerup',e=>{if(!touchDrag||touchDrag.pointer!==e.pointerId)return;const drop=touchDrag;watchlistReorderActive=false;if(drop.target)moveProject(drop.source,drop.target,drop.after);endReorder()});
document.addEventListener('pointercancel',()=>{if(touchDrag)endReorder()});
document.addEventListener('keydown',e=>{const handle=e.target.closest('[data-reorder-handle]');if(e.key==='Escape'&&watchlistReorderActive){endReorder();return}if(!handle||!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const source=handle.dataset.reorderHandle,list=orderedProjects().map(p=>p.id),direction=['ArrowDown','ArrowRight'].includes(e.key)?1:-1,target=list[list.indexOf(source)+direction];if(target){moveProject(source,target,direction>0);document.querySelector('[data-reorder-handle="'+source+'"]').focus();toast('项目顺序已调整')}});
render();
